/**
 * Leap months for four versions of the Tibetan calendar, one row per Gregorian year.
 *
 * This is the only *external* check the engine has for any tradition but Phugpa, and it is
 * available because leap months depend on nothing astronomical: the intercalation index is built
 * from the epoch year, the epoch month and the tradition's leap-index threshold alone. So a
 * Tsurphu or Mongolian config can be validated here without any of its mean-motion constants.
 *
 * Two columns need their conventions stated.
 *
 * **Tsurphu and Mongolian are identical throughout**, which Janson states in prose and the
 * extractor asserts while parsing — a mis-read column cannot reach this file.
 *
 * **The Bhutanese column uses Bhutanese numbering**, in which a leap month takes the number of the
 * *preceding* month. This package numbers a leap month from the month that follows it, so its
 * output is expected to differ from this column, and the difference is the convention rather than
 * an error.
 *
 * @remarks
 * GENERATED by `scripts/extract-janson-fixtures.mjs` from the LaTeX source of arXiv:1401.6285.
 * Do not edit by hand — re-run the script instead.
 *
 * A table of dates and traditional names: facts rather than copyrightable expression, which is
 * what makes it usable directly under this project's clean-room constraint.
 */
export interface CrossVersionLeapRow {
	/** Janson's *Y* — the Gregorian year the Tibetan year begins in. */
	year: number;
	/**
	 * Whether the row is commented out in Janson's source rather than printed in the paper.
	 *
	 * He prints 2000-2020 and leaves 2021-2030 commented. The commented rows are his own computed
	 * values and are kept, flagged, because CLAUDE.md's rule is to read the LaTeX rather than the
	 * rendered output — but a claim resting on them should say which tier it is using.
	 */
	commented: boolean;
	/** Leap month number, or `undefined` for a year with no leap month. */
	phugpa: number | undefined;
	tsurphu: number | undefined;
	mongolian: number | undefined;
	/** In Bhutanese numbering — see the note above. */
	bhutanese: number | undefined;
}

